  "login.welcome": { en:"Welcome back to FarmLens", hi:"FarmLens में वापस स्वागत है", bn:"FarmLens-এ স্বাগতম", te:"FarmLens కి స్వాగతం", mr:"FarmLens मध्ये परत स्वागत", ta:"FarmLens-க்கு வரவேற்கிறோம்", gu:"FarmLens માં પાછા સ્વાગત", kn:"FarmLens ಗೆ ಮರಳಿ ಸ್ವಾಗತ", pa:"FarmLens ਵਿੱਚ ਵਾਪਸ ਸੁਆਗਤ", or:"FarmLens ରେ ପୁଣି ସ୍ୱାଗତ", ml:"FarmLens-ലേക്ക് തിരിച്ചു സ്വാഗതം" },
  "login.subtitle":{ en:"Monitor and manage your crops effortlessly", hi:"अपनी फसलों की आसानी से निगरानी करें", bn:"সহজেই আপনার ফসল পর্যবেক্ষণ করুন", te:"మీ పంటలను సులభంగా నిర్వహించండి", mr:"तुमच्या पिकांचे सहज व्यवस्थापन करा", ta:"உங்கள் பயிர்களை எளிதாக நிர்வகிக்கவும்", gu:"તમારા પાકને સરળતાથી સંચાલિત કરો", kn:"ನಿಮ್ಮ ಬೆಳೆಗಳನ್ನು ಸುಲಭವಾಗಿ ನಿರ್ವಹಿಸಿ", pa:"ਆਪਣੀਆਂ ਫਸਲਾਂ ਨੂੰ ਆਸਾਨੀ ਨਾਲ ਪ੍ਰਬੰਧਿਤ ਕਰੋ", or:"ଆପଣଙ୍କ ଫସଲ ସହଜରେ ପରିଚାଳନା କରନ୍ତୁ", ml:"നിങ്ങളുടെ വിളകൾ എളുപ്പത്തിൽ നിയന്ത്രിക്കുക" },
  "login.email":   { en:"Email", hi:"ईमेल", bn:"ইমেইল", te:"ఇమెయిల్", mr:"ईमेल", ta:"மின்னஞ்சல்", gu:"ઇમેઇલ", kn:"ಇಮೇಲ್", pa:"ਈਮੇਲ", or:"ଇମେଲ", ml:"ഇമെയിൽ" },
  "login.password":{ en:"Password", hi:"पासवर्ड", bn:"পাসওয়ার্ড", te:"పాస్‌వర్డ్", mr:"पासवर्ड", ta:"கடவுச்சொல்", gu:"પાસવર્ડ", kn:"ಪಾಸ್‌ವರ್ಡ್", pa:"ਪਾਸਵਰਡ", or:"ପାସୱାର୍ଡ", ml:"പാസ്‌വേഡ്" },
