  "login.create_account": { en:"Create an account", hi:"खाता बनाएं", bn:"অ্যাকাউন্ট তৈরি করুন", te:"ఖాతా సృష్టించండి", mr:"खाते तयार करा", ta:"கணக்கை உருவாக்கவும்", gu:"એકાઉન્ટ બનાવો", kn:"ಖಾತೆ ರಚಿಸಿ", pa:"ਖਾਤਾ ਬਣਾਓ", or:"ଖାତା ତିଆରି କରନ୍ତୁ", ml:"അക്കൗണ്ട് ഉണ്ടാക്കുക" },
  "login.signup_subtitle": { en:"Sign up to get started with FarmLens", hi:"FarmLens के साथ शुरुआत करने के लिए साइन अप करें", bn:"FarmLens শুরু করতে সাইন আপ করুন", te:"FarmLens తో ప్రారంభించడానికి సైన్ అప్ చేయండి", mr:"FarmLens सुरू करण्यासाठी साइन अप करा", ta:"FarmLens தொடங்க பதிவு செய்யவும்", gu:"FarmLens સાથે શરૂ કરવા સાઇન અપ કરો", kn:"FarmLens ಪ್ರಾರಂಭಿಸಲು ಸೈನ್ ಅಪ್ ಮಾಡಿ", pa:"FarmLens ਸ਼ੁਰੂ ਕਰਨ ਲਈ ਸਾਈਨ ਅੱਪ ਕਰੋ", or:"FarmLens ଆରମ୍ଭ କରିବାକୁ ସାଇନ ଅପ କରନ୍ତୁ", ml:"FarmLens ആരംഭിക്കാൻ സൈൻ അപ്പ് ചെയ്യുക" },
