  "profile.unknown_crop": { en:"Unknown crop", hi:"अज्ञात फसल", bn:"অজানা ফসল", te:"తెలియని పంట", mr:"अज्ञात पीक", ta:"தெரியாத பயிர்", gu:"અજ્ઞાત પાક", kn:"ಅಜ್ಞಾತ ಬೆಳೆ", pa:"ਅਣਜਾਣ ਫਸਲ", or:"ଅଜଣା ଫସଲ", ml:"അജ്ഞാത വിള" },
  "profile.personalized_treatment": { en:"Personalized Treatment", hi:"व्यक्तिगत उपचार", bn:"ব্যক্তিগতকৃত চিকিৎসা", te:"వ్యక్తిగతీకరించిన చికిత్స", mr:"वैयक्तिक उपचार", ta:"தனிப்பயன் சிகிச்சை", gu:"વ્યક્તિગત સારવાર", kn:"ವೈಯಕ್ತಿಕಗೊಳಿಸಿದ ಚಿಕಿತ್ಸೆ", pa:"ਨਿੱਜੀ ਇਲਾਜ", or:"ବ୍ୟକ୍ତିଗତ ଚିକିତ୍ସା", ml:"വ്യക്തിഗത ചികിത്സ" },
  "profile.symptoms": { en:"Symptoms to Watch", hi:"ध्यान देने योग्य लक्षण", bn:"লক্ষণীয় উপসর্গ", te:"గమనించాల్సిన లక్షణాలు", mr:"लक्ष देण्यासारखी लक्षणे", ta:"கவனிக்க வேண்டிய அறிகுறிகள்", gu:"ધ્યાન આપવા લાયક લક્ષણો", kn:"ಗಮನಿಸಬೇಕಾದ ಲಕ್ಷಣಗಳು", pa:"ਧਿਆਨ ਦੇਣ ਵਾਲੇ ਲੱਛਣ", or:"ଲକ୍ଷ୍ୟ ରଖିବା ଯୋଗ୍ୟ ଲକ୍ଷଣ", ml:"ശ്രദ്ധിക്കേണ്ട ലക്ഷണങ്ങൾ" },
