"farm.error_load_title": { en:"Could not load farms", hi:"फार्म लोड नहीं हो सके", bn:"ফার্ম লোড করা যায়নি", te:"ఫారమ్లను లోడ్ చేయలేకపోయాము", mr:"शेते लोड करता आली नाहीत", ta:"பண்ணைகளை ஏற்ற முடியவில்லை", gu:"ફાર્મ લોડ કરી શકાયા નહીં", kn:"ಫಾರಮ್‌ಗಳನ್ನು ಲೋಡ್ ಮಾಡಲಾಗಲಿಲ್ಲ", pa:"ਫਾਰਮ ਲੋਡ ਨਹੀਂ ਹੋ ਸਕੇ", or:"ଫାର୍ମ ଲୋଡ କରାଯାଇପାରିଲା ନାହିଁ", ml:"ഫാമുകൾ ലോഡ് ചെയ്യാനായില്ല" },
  "farm.error_load": { en:"Failed to load farms.", hi:"फार्म लोड करने में विफल।", bn:"ফার্ম লোড করতে ব্যর্থ।", te:"ఫారమ్లను లోడ్ చేయడంలో విఫలమైంది.", mr:"शेते लोड करण्यात अयशस्वी.", ta:"பண்ணைகளை ஏற்ற முடியவில்லை.", gu:"ફાર્મ લોડ કરવામાં નિષ્ફળ.", kn:"ಫಾರಮ್‌ಗಳನ್ನು ಲోడ్ ಮಾಡುವಲ್ಲಿ విఫಲವಾಗಿದೆ.", pa:"ਫਾਰਮ ਲੋਡ ਕਰਨ ਵਿੱਚ ਅਸਫਲ।", or:"ଫାର୍ମ ଲୋଡ କରିବାରେ ବିଫଳ।", ml:"ഫാമുകൾ ലോഡ് ചെയ്യുന്നതിൽ പരാജയപ്പെട്ടു." },
  "farm.delete_title": { en:"Delete farm?", hi:"फार्म हटाएं?", bn:"ফার্ম মুছবেন?", te:"ఫారం తొలగించాలా?", mr:"शेत हटवायचे?", ta:"பண்ணையை நீக்கவா?", gu:"ફાર્મ કાઢી નાખવું?", kn:"ಫಾರ್ಮ್ ಅಳಿಸಬೇಕೆ?", pa:"ਫਾਰਮ ਹਟਾਉਣਾ ਹੈ?", or:"ଫାର୍ମ ବିଲୋପ କରିବେ?", ml:"ഫാം ഇല്ലാതാക്കണോ?" },
  "farm.delete_desc": { en:"This will permanently delete “{name}” and all of its fields. This action cannot be undone.", hi:"यह “{name}” और इसके सभी क्षेत्रों को स्थायी रूप से हटा देगा। यह क्रिया पूर्ववत नहीं की जा सकती।", bn:"এটি “{name}” এবং এর সমস্ত ক্ষেত্র স্থায়ীভাবে মুছে ফেলবে। এই কাজটি বাতিল করা যাবে না।", te:"ఇది “{name}” మరియు దాని అన్ని ఫీల్డ్‌లను శాశ్వతంగా తొలగిస్తుంది. ఈ చర్యను రద్దు చేయలేరు.", mr:"हे “{name}” आणि त्याची सर्व शेते कायमचे हटवेल. ही क्रिया पूर्ववत करता येणार नाही.", ta:"இது “{name}” மற்றும் அதன் அனைத்து வயல்களையும் நிரந்தரமாக நீக்கும். இந்தச் செயலை செயல்தவிர்க்க முடியாது.", gu:"આ “{name}” અને તેના બધા ફીલ્ડ કાયમ માટે કાઢી નાખશે. આ ક્રિયા પાછી ખેંચી શકાતી નથી.", kn:"ಇದು “{name}” ಮತ್ತು ಅದರ ಎಲ್ಲಾ ಫೀಲ್ಡ್‌ಗಳನ್ನು ಶಾಶ್ವತವಾಗಿ ಅಳಿಸುತ್ತದೆ. ಈ ಕ್ರಿಯೆಯನ್ನು ಹಿಂತೆಗೆದುಕೊಳ್ಳಲಾಗುವುದಿಲ್ಲ.", pa:"ਇਹ “{name}” ਅਤੇ ਇਸ ਦੀਆਂ ਸਾਰੀਆਂ ਫੀਲਡਾਂ ਨੂੰ ਸਥਾਈ ਤੌਰ ’ਤੇ ਹਟਾ ਦੇਵੇਗਾ। ਇਹ ਕਿਰਿਆ ਵਾਪਸ ਨਹੀਂ ਕੀਤੀ ਜਾ ਸਕਦੀ।", or:"ଏହା “{name}” ଏବଂ ଏହାର ସମସ୍ତ କ୍ଷେତ୍ରକୁ ସ୍ଥାୟୀ ଭାବେ ବିଲୋପ କରିବ। ଏହି କାର୍ଯ୍ୟ ପୂର୍ବାବସ୍ଥାକୁ ଫେରାଯାଇପାରିବ ନାହିଁ।", ml:"ഇത് “{name}”-നെയും അതിലെ എല്ലാ ഫീൽഡുകളെയും സ്ഥിരമായി ഇല്ലാതാക്കും. ഈ പ്രവർത്തനം പഴയപടിയാക്കാനാവില്ല." },
  "farm.delete_action": { en:"Delete farm", hi:"फार्म हटाएं", bn:"ফার্ম মুছুন", te:"ఫారం తొలగించండి", mr:"शेत हटवा", ta:"பண்ணையை நீக்கு", gu:"ફાર્મ કાઢી નાખો", kn:"ಫಾರ್ಮ್ ಅಳಿಸಿ", pa:"ਫਾਰਮ ਹਟਾਓ", or:"ଫାର୍ମ ବିଲୋପ କରନ୍ତୁ", ml:"ഫാം ഇല്ലാതാക്കുക" },
