"farm.toast.field_added": { en:"Field added", hi:"क्षेत्र जोड़ा गया", bn:"ক্ষেত্র যোগ হয়েছে", te:"ఫీల్డ్ జోడించబడింది", mr:"शेत जोडले", ta:"வயல் சேர்க்கப்பட்டது", gu:"ફીલ્ડ ઉમેરાયો", kn:"ಫೀಲ್ಡ್ ಸೇರಿಸಲಾಗಿದೆ", pa:"ਫੀਲਡ ਜੋੜਿਆ ਗਿਆ", or:"କ୍ଷେତ୍ର ଯୋଡ଼ାଯାଇଛି", ml:"ഫീൽഡ് ചേർത്തു" },
  "farm.toast.field_added_desc": { en:"“{name}” has been added to “{farm}”.", hi:"“{name}” को “{farm}” में जोड़ दिया गया है।", bn:"“{name}” “{farm}”-এ যোগ করা হয়েছে।", te:"“{name}” “{farm}”కి జోడించబడింది.", mr:"“{name}” “{farm}” मध्ये जोडले गेले आहे.", ta:"“{name}” “{farm}”-இல் சேர்க்கப்பட்டது.", gu:"“{name}” “{farm}”માં ઉમેરાયો છે.", kn:"“{name}” “{farm}”ಗೆ ಸೇರಿಸಲಾಗಿದೆ.", pa:"“{name}” ਨੂੰ “{farm}” ਵਿੱਚ ਜੋੜਿਆ ਗਿਆ ਹੈ।", or:"“{name}” କୁ “{farm}” ରେ ଯୋଡ଼ାଯାଇଛି।", ml:"“{name}” “{farm}”-ലേക്ക് ചേർത്തു." },
  "farm.toast.field_updated": { en:"Field updated", hi:"क्षेत्र अपडेट किया गया", bn:"ক্ষেত্র আপডেট হয়েছে", te:"ఫీల్డ్ నవీకరించబడింది", mr:"शेत अपडेट झाले", ta:"வயல் புதுப்பிக்கப்பட்டது", gu:"ફીલ્ડ અપડેટ થયો", kn:"ಫೀಲ್ಡ್ ನವೀಕರಿಸಲಾಗಿದೆ", pa:"ਫੀਲਡ ਅੱਪਡੇਟ ਹੋਇਆ", or:"କ୍ଷେତ୍ର ଅପଡେଟ ହେଲା", ml:"ഫീൽഡ് അപ്ഡേറ്റ് ചെയ്തു" },
